function solveHomography(points){const target=[[0,0],[1,0],[1,1],[0,1]],matrix=[];let area=0,sign=0;for(let i=0;i<4;i++){const p=points[i],q=points[(i+1)%4],r=points[(i+2)%4],cross=(q.x-p.x)*(r.y-q.y)-(q.y-p.y)*(r.x-q.x);area+=p.x*q.y-q.x*p.y;if(Math.abs(cross)<.0001||sign&&Math.sign(cross)!==sign)throw Error('Invalid corners');sign=Math.sign(cross);}if(Math.abs(area)<.01)throw Error('Corners too close');points.forEach(({x,y},i)=>{const [u,v]=target[i];matrix.push([x,y,1,0,0,0,-u*x,-u*y,u],[0,0,0,x,y,1,-v*x,-v*y,v]);});for(let i=0;i<8;i++){let pivot=i;for(let j=i+1;j<8;j++)if(Math.abs(matrix[j][i])>Math.abs(matrix[pivot][i]))pivot=j;[matrix[i],matrix[pivot]]=[matrix[pivot],matrix[i]];const divisor=matrix[i][i];if(Math.abs(divisor)<1e-10)throw Error('Singular map');for(let k=i;k<9;k++)matrix[i][k]/=divisor;for(let j=0;j<8;j++)if(j!==i){const factor=matrix[j][i];for(let k=i;k<9;k++)matrix[j][k]-=factor*matrix[i][k];}}return matrix.map(row=>row[8]);}
