async function importVideo(file) {
  if (!file) return;
  if (jobId || recording) { toast('Finish or cancel the current analysis/export first.'); return; }
  if (file.size > 2 * 1024 ** 3) { toast('Please use a clip smaller than 2 GB.'); return; }
  // Validate a separate media element before replacing the current session.
  const candidateURL = URL.createObjectURL(file);
  const candidate = document.createElement('video');
  candidate.preload = 'metadata';
  let candidateDuration;
  try {
    await new Promise((resolve, reject) => {
      const timeout = setTimeout(() => finish(new Error('Video metadata timed out')), 15000);
      function finish(error) {
        clearTimeout(timeout);
        candidate.onloadedmetadata = null;
        candidate.onerror = null;
        error ? reject(error) : resolve();
      }
      candidate.onloadedmetadata = () => finish();
      candidate.onerror = () => finish(new Error('Unsupported video'));
      candidate.src = candidateURL;
    });
    candidateDuration = candidate.duration;
    if (!Number.isFinite(candidateDuration) || candidateDuration <= 0) throw Error('Invalid duration');
  } catch {
    URL.revokeObjectURL(candidateURL);
    toast('This video could not be opened. Your current clip and edits are intact.');
    return;
  } finally {
    candidate.removeAttribute('src');
    candidate.load();
  }
  // A job may have started while the metadata was being read.
  if (jobId || recording) { URL.revokeObjectURL(candidateURL); return; }
  const relink = state.sourceName === file.name && !state.demo;
  clearMedia();
  clipFile = file;
  objectURL = candidateURL;
  video.src = objectURL;
  if (!relink) {
    frames = []; trackMeta = null; state.annotations = []; state.players = {};state.connections=[];connectionFrom=null;
    state.calibration = null; state.timedNotes = []; state.kitColorsSwapped = false;
    state.title = file.name.replace(/\.[^.]+$/, ''); undoStack = []; selected = null;
  }
  state.demo = false; state.sourceName = file.name; state.clipDuration = candidateDuration;
  needsRelink = false; duration = candidateDuration; time = 0;
  refreshClipUI(); updateSelection(); autosave(); storeTracks();
  toast(relink ? 'Video re-linked. Your edits are ready.' : 'Video imported. Draw now or run player tracking.');
}
