async function checkEngine(){localEngine=false;cloudEngine=false;engineReady=false;phoneUrl=null;try{const response=await fetch('/api/health',{signal:AbortSignal.timeout(3000)});if(response.ok){const h=await response.json();phoneUrl=h.phone_url||null;localEngine=h.app==='touchline-studio'&&h.mode!=='cloud';cloudEngine=h.app==='touchline-studio'&&h.mode==='cloud';engineReady=!!h.ready;}}catch{}updateEngineStatus();if(cloudEngine&&engineReady&&!jobId){const saved=localStorage.getItem(activeCloudJobKey);if(saved&&/^[a-f0-9]{32}$/.test(saved)){jobId=saved;$('analysisProgress').hidden=false;updateEngineStatus();pollAnalysis(++jobGeneration);}}}
function updateEngineStatus(){let text=cloudEngine?(engineReady?'Private cloud runner ready':'Private cloud setup needed'):state.demo?'Demo tracking active':frames.length?'Player tracking ready':engineReady?'Local YOLO runner ready':localEngine?'Tracking dependencies needed':'Local YOLO app required';$('engineStatus').querySelector('span').textContent=text;$('trackingHelp').textContent=cloudEngine?'Uploads go to private cloud storage. Raw clips are deleted after processing; sampled pseudo-labels and candidate models are retained but stay inactive. Cloud training uses the specialized football model.':state.demo?'Import your footage to run local player tracking.':frames.length?(Object.keys(trackMeta?.team_assignments||{}).length?'Kit-color groups ready. Review, swap, or correct any track.':'Select tracks to assign teams; kit-color evidence was insufficient.'):engineReady?'Runs on your computer. Your footage stays local.':'Use the desktop app for automatic tracking.';const phoneButton=$('phoneConnectLink');if(phoneButton)phoneButton.hidden=!phoneUrl;const modelChoice=$('modelChoice');if(modelChoice){modelChoice.disabled=cloudEngine;if(cloudEngine)modelChoice.value='football-best.pt';}$('analyzeButton').disabled=!!jobId;}
function runnerDialog(){modal('Run YOLO on your computer',`<p>The browser workspace supports video playback, drawings, formation planning, and notes. Automatic tracking runs in the included local app.</p><ol><li>Download and extract <strong>Touchline Studio</strong>.</li><li>Double-click <strong>Start Touchline.cmd</strong>. First launch installs the tracking packages.</li><li>Import a match video and choose <strong>Analyze uploaded video</strong>.</li></ol><p>The runner defaults to the football-trained detector with camera-aware BoT-SORT. YOLO26 fallbacks and ByteTrack are available in Tracking settings. Foot circles follow the bottom center of each detected person. Review automatic kit-color groups and check track IDs after occlusion or a camera cut.</p><a class="button primary" href="touchline-studio.zip" download>Download local app</a><button class="button" id="importTrackButton">Import tracking JSON</button><p class="microcopy">Windows · Python 3.11–3.13 · Internet needed for first setup. Video processing stays local.</p>`);$('importTrackButton').onclick=()=>{$('modal').close();$('trackingInput').click();};}
$('desktopDownload').onclick=runnerDialog;$('phoneConnectLink').onclick=()=>{if(!phoneUrl){toast('Restart Touchline with phone access enabled.');return;}const safeUrl=phoneUrl.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');modal('Connect your phone',`<p>Connect the phone to the same Wi-Fi, then open this link:</p><p><a href="${safeUrl}" target="_blank" rel="noopener noreferrer">${safeUrl}</a></p><button class="button primary" id="copyPhoneLink">Copy phone link</button>`);$('copyPhoneLink').onclick=async()=>{try{await navigator.clipboard.writeText(phoneUrl);toast('Phone link copied.');}catch{toast('Select and copy the phone link above.');}};};
$('teamHelp').onclick=()=>{modal('Assign your players',`<p>Choose the pointer tool and click a player in the video. In the selection panel you can:</p><ul><li>Set <strong>Home</strong>, <strong>Away</strong>, or <strong>Exclude</strong> for referees and staff.</li><li>Replace the track ID with a shirt number or player name.</li><li>Enable <strong>Link to team shape</strong> for the players you want connected.</li></ul><p>Connection lines join your selected tracks from top to bottom. Use Swap home / away if the two detected kit groups are reversed. Use the line tool for a specific defensive or midfield line. Tracking IDs are temporary identities, not automatic jersey recognition.</p>`);};
$('analyzeButton').onclick=async()=>{if(state.demo||!clipFile){toast('Import your match video first.');$('videoInput').click();return;}await checkEngine();if(jobId){toast('An analysis job is already active.');return;}if(!localEngine&&!cloudEngine){runnerDialog();return;}if(!engineReady){modal(cloudEngine?'Cloud service is not configured':'Finish local setup',cloudEngine?'<p>The private cloud service is not ready yet. Check the deployment settings or contact the site owner.</p>':`<p>The workspace is running, but YOLO is not installed yet. Close this server and run <strong>Start Touchline.cmd</strong> to install the tracking dependencies, then reopen your saved project.</p>`);return;}if(frames.length){modal('Run tracking again?',`<p>New detections may have different IDs. This resets player assignments and pitch calibration. Your drawings and notes stay in place.</p><button class="button primary" id="confirmAnalyze">Run tracking again</button>`);$('confirmAnalyze').onclick=()=>{$('modal').close();startAnalysis();};}else startAnalysis();};
async function startAnalysis(){
 setPlaying(false);const generation=++jobGeneration;jobId='uploading';$('analysisProgress').hidden=false;$('progress').value=0;
 $('progressText').textContent=cloudEngine?'Preparing private cloud upload…':'Sending video to local runner…';updateEngineStatus();
 try{
  const settings={model_name:$('modelChoice').value,confidence:Number($('confidence').value),stride:Number($('frameStride').value),tracker_name:$('trackerChoice').value,with_reid:$('enableReID')?Boolean($('enableReID').checked):true,imgsz:Number($('imageSize').value)};
  if(cloudEngine){
   if(settings.model_name!=='football-best.pt')throw Error('Cloud candidate training currently requires the specialized football model.');
   if(clipFile.size>2*1024**3)throw Error('Cloud uploads must be smaller than 2 GB.');
   uploadController=new AbortController();
   const created=await fetch('/api/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:clipFile.name,settings}),signal:uploadController.signal});
   const ticket=await created.json();if(!created.ok)throw Error(ticket.error||'Could not prepare cloud upload');
   jobId=ticket.id;window.localStorage.setItem(activeCloudJobKey,jobId);updateEngineStatus();if(generation!==jobGeneration){await fetch('/api/jobs/'+jobId,{method:'DELETE'});jobId=null;return;}
   const parts=[];let uploaded=0;
   for(const part of ticket.parts){
    const start=(part.part_number-1)*ticket.part_size;if(start>=clipFile.size)break;
    const end=Math.min(start+ticket.part_size,clipFile.size),body=clipFile.slice(start,end);
    $('progressText').textContent=`Uploading video · part ${part.part_number} · ${(uploaded/1048576).toFixed(0)} of ${(clipFile.size/1048576).toFixed(0)} MB`;
    const put=await fetch(part.upload_url,{method:'PUT',headers:ticket.upload_headers,body,signal:uploadController.signal});
    if(!put.ok)throw Error(`Video upload part ${part.part_number} failed. Retry the upload.`);
    const etag=put.headers?.get('ETag');if(!etag)throw Error('Storage did not return an upload part tag. Check the bucket CORS settings.');
    parts.push({PartNumber:part.part_number,ETag:etag});uploaded=end;
    $('progress').value=3+Math.round(5*uploaded/clipFile.size);
   }
   const completed=await fetch('/api/jobs/'+jobId+'/complete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({parts}),signal:uploadController.signal});
   const completion=await completed.json();if(!completed.ok)throw Error(completion.error||'Could not finalize the video upload');
   if(generation!==jobGeneration){await fetch('/api/jobs/'+jobId,{method:'DELETE'});jobId=null;return;}
   $('progress').value=8;$('progressText').textContent='Queueing cloud GPU tracking and candidate training…';
   const started=await fetch('/api/jobs/'+jobId+'/start',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',signal:uploadController.signal});
   const queued=await started.json();if(!started.ok)throw Error(queued.error||'Could not queue the cloud job');
   uploadController=null;pollAnalysis(generation);return;
  }
  const params=new URLSearchParams({filename:clipFile.name,model:settings.model_name,conf:String(settings.confidence),stride:String(settings.stride),tracker:settings.tracker_name,reid:settings.with_reid?'1':'0',imgsz:String(settings.imgsz)});
  const r=await fetch('/api/jobs?'+params,{method:'POST',headers:{'Content-Type':'application/octet-stream','X-Touchline-Client':'studio'},body:clipFile});
  const data=await r.json();if(!r.ok)throw Error(data.error||'Could not start analysis');jobId=data.id;
  if(generation!==jobGeneration){await fetch('/api/jobs/'+data.id,{method:'DELETE',headers:{'X-Touchline-Client':'studio'}});jobId=null;updateEngineStatus();return;}
  pollAnalysis(generation);
 }catch(e){
  uploadController=null;if(generation!==jobGeneration)return;
  if(cloudEngine&&jobId&&jobId!=='uploading')try{await fetch('/api/jobs/'+jobId,{method:'DELETE'});}catch{}
  jobId=null;window.localStorage.removeItem(activeCloudJobKey);$('analysisProgress').hidden=true;updateEngineStatus();toast(e.name==='AbortError'?'Upload cancelled.':e.message);
 }
}
async function pollAnalysis(generation){if(!jobId||generation!==jobGeneration)return;try{const r=await fetch('/api/jobs/'+jobId);const j=await r.json();if(generation!==jobGeneration)return;if(!r.ok)throw Error(j.error||'Could not read analysis status');$('progress').value=j.progress||0;$('progressText').textContent=j.message||'Tracking players…';if(j.status==='completed'){const completedJobId=jobId;const result=await fetch('/api/jobs/'+completedJobId+'/result').then(r=>r.json());if(generation!==jobGeneration)return;checkpoint();loadTracking(result);state.players={};state.connections=[];connectionFrom=null;state.calibration=null;selected=null;updateSelection();jobId=null;window.localStorage.removeItem(activeCloudJobKey);$('analysisProgress').hidden=true;updateEngineStatus();autosave();const trainingNote=j.training?.status==='candidate-only'?' An experimental candidate was saved and is not active.':j.training?.status==='failed'?' Tracking succeeded, but candidate training failed.':j.training?.status==='skipped'?' Tracking succeeded; this upload did not produce enough reliable pseudo-labels to train.':'';toast(`Tracking complete. ${Object.keys(result.team_assignments||{}).length} tracks grouped by kit color. Review teams and labels.${trainingNote}`);if(cloudEngine&&j.training?.status==='candidate-only')modal('Experimental candidate saved',`<p>The candidate used prediction-generated labels from retained sample frames. It remains inactive because no reviewed benchmark has shown an improvement.</p><a class="button primary" href="/api/jobs/${completedJobId}/candidate" download>Download candidate checkpoint</a><a class="button" href="/api/jobs/${completedJobId}/candidate-manifest" download>Download provenance</a><p class="microcopy">The verified football model remains active. Review a candidate on separate, manually labeled matches before using it.</p>`);}else if(j.status==='failed'||j.status==='cancelled'){throw Error(j.error||'Analysis cancelled');}else setTimeout(()=>pollAnalysis(generation),1200);}catch(e){if(generation!==jobGeneration)return;jobId=null;window.localStorage.removeItem(activeCloudJobKey);$('analysisProgress').hidden=true;updateEngineStatus();toast(e.message);}}
$('cancelAnalysis').onclick=async()=>{const generation=++jobGeneration;if(uploadController){uploadController.abort();uploadController=null;}if(jobId&&jobId!=='uploading'){try{const r=await fetch('/api/jobs/'+jobId,{method:'DELETE',headers:localEngine?{'X-Touchline-Client':'studio'}:{}});if(!r.ok){const data=await r.json().catch(()=>({}));jobGeneration=generation;toast(data.error||'Could not confirm cancellation.');pollAnalysis(generation);return;}}catch{jobGeneration=generation;toast('Could not confirm cancellation. Checking job status.');pollAnalysis(generation);return;}}jobId=null;window.localStorage.removeItem(activeCloudJobKey);$('analysisProgress').hidden=true;updateEngineStatus();toast('Cancellation requested.');};
function validateTracking(data){if(!data||data.schema!=='touchline-tracks-v1'||!Array.isArray(data.frames)||data.frames.length>250000)throw Error('Invalid Touchline tracking file');if(!Number.isFinite(data.fps)||data.fps<=0||!Number.isFinite(data.stride)||data.stride<1)throw Error('Invalid tracking timing');let last=-1;for(const f of data.frames){if(!Number.isFinite(f.t)||f.t<=last||f.t<0||!Array.isArray(f.players)||f.players.length>300)throw Error('Invalid tracking frames');last=f.t;if(f.camera&&!validateCamera(f.camera))throw Error('Invalid camera transform');if(f.ball&&!['x','y','w','h'].every(k=>Number.isFinite(f.ball[k])&&f.ball[k]>=0&&f.ball[k]<=1.1))throw Error('Invalid ball position');for(const p of f.players){if(!Number.isInteger(p.id)||!['x','y','w','h'].every(k=>Number.isFinite(p[k])&&p[k]>=0&&p[k]<=1.1))throw Error('Invalid player positions');}}return data;}
function loadTracking(raw){const d=validateTracking(raw);state.kitColorsSwapped=false;frames=d.frames;const {frames:unusedFrames,...metadata}=d;trackMeta=metadata;storeTracks();updateEngineStatus();}
$('trackingInput').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>400*1024**2)throw Error('Tracking file is too large');if(state.demo||!clipFile)throw Error('Import the matching video first');const data=JSON.parse(await f.text());if(data.source_name&&data.source_name!==clipFile.name)throw Error('This tracking file belongs to a different video');checkpoint();loadTracking(data);state.players={};state.connections=[];connectionFrom=null;state.calibration=null;selected=null;updateSelection();autosave();toast('Tracking imported. Review automatic teams and select players to correct them.');}catch(err){toast(err.message);}e.target.value='';};
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function saveProject(){const data={...state,duration,tracking:frames.length?{schema:'touchline-tracks-v1',...trackMeta,frames}:null};download(new Blob([JSON.stringify(data)],{type:'application/json'}),'touchline-project.json');toast('Project saved. Keep the original video to re-link it later.');}
$('saveProject').onclick=saveProject;$('openProject').onclick=()=>$('projectInput').click();
function sanitizeProject(d){if(d?.version!==1||!Array.isArray(d.annotations))throw Error('Not a Touchline project file');const next={version:1,demo:d.demo===true,kitColorsSwapped:d.kitColorsSwapped===true,clipDuration:Number.isFinite(d.clipDuration)&&d.clipDuration>0?d.clipDuration:60,sourceName:String(d.sourceName||'').slice(0,255),title:String(d.title||'Match analysis').slice(0,100),notes:String(d.notes||'').slice(0,20000),timedNotes:[],annotations:[],connections:[],players:{},settings:{...defaults},boardTeam:d.boardTeam==='away'?'away':'home',preset:['4-3-3','4-4-2','4-2-3-1','3-5-2','3-4-3'].includes(d.preset)?d.preset:'4-3-3',boards:{},calibration:null};
 for(const [k,v] of Object.entries(defaults)){if(typeof v==='boolean')next.settings[k]=typeof d.settings?.[k]==='boolean'?d.settings[k]:v;else if(k.includes('Color'))next.settings[k]=cleanColor(d.settings?.[k]||v);}next.settings.ringSize=clamp(Number(d.settings?.ringSize)||18,8,36);next.settings.overlayOpacity=clamp(Number(d.settings?.overlayOpacity)||90,20,100);
 for(const a of d.annotations.slice(0,2000)){if(!['line','arrow','circle','zone','text'].includes(a.type)||!['x','y','x2','y2','start','end'].every(k=>Number.isFinite(a[k])))throw Error('Invalid drawing in project');next.annotations.push({id:String(a.id),type:a.type,x:clamp(a.x,0,1),y:clamp(a.y,0,1),x2:clamp(a.x2,0,1),y2:clamp(a.y2,0,1),start:Math.max(0,a.start),end:Math.max(a.start,a.end),color:cleanColor(a.color),width:clamp(Number(a.width)||3,1,12),text:String(a.text||'').slice(0,500)});}
 for(const [id,p] of Object.entries(d.players||{})){if(!/^\d+$/.test(id))continue;next.players[id]={name:String(p.name??'').slice(0,30),team:['home','away','neutral','hidden'].includes(p.team)?p.team:'neutral',linked:p.linked===true,keepVisible:p.keepVisible===true,colorOverride:/^#[0-9a-f]{6}$/i.test(p.colorOverride||'')?p.colorOverride:undefined,footX:clamp(Number(p.footX)||0,-50,50),footY:clamp(Number(p.footY)||0,-50,50)};}
 for(const team of ['home','away'])if(Array.isArray(d.boards?.[team]))next.boards[team]=d.boards[team].slice(0,11).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)).map(p=>({id:Number(p.id)||1,x:clamp(p.x,0,1),y:clamp(p.y,0,1)}));
 next.connections=PlayerConnections.sanitize(d.connections);
 next.timedNotes=(Array.isArray(d.timedNotes)?d.timedNotes:[]).slice(0,1000).filter(n=>Number.isFinite(n.time)).map(n=>({id:String(n.id),time:Math.max(0,n.time),text:String(n.text||'').slice(0,500)}));if(d.calibration?.points?.length===4){const points=d.calibration.points;if(points.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y))){try{next.calibration={points,homography:solveHomography(points),at:d.calibration.at||0,camera:validateCamera(d.calibration.camera)?d.calibration.camera:null};}catch{next.calibration=null;}}}return next;
}
$('projectInput').onchange=async e=>{try{if(jobId||recording)throw Error('Finish the current operation first');const f=e.target.files[0];if(!f)return;if(f.size>400*1024**2)throw Error('Project file is too large');const d=JSON.parse(await f.text()),next=sanitizeProject(d);if(d.tracking)validateTracking(d.tracking);const keepVideo=clipFile&&clipFile.name===next.sourceName&&!next.demo;if(!keepVideo)clearMedia();state=next;connectionFrom=null;frames=d.tracking?.frames||[];trackMeta=d.tracking?Object.fromEntries(Object.entries(d.tracking).filter(([key])=>key!=='frames')):null;duration=state.demo?60:keepVideo?video.duration:Number(d.duration)||60;needsRelink=!state.demo&&!keepVideo;time=0;selected=null;undoStack=[];for(const t of ['home','away'])if(!state.boards[t]?.length)initBoard(state.preset,t);$('formationPreset').value=state.preset;document.querySelectorAll('[data-board-team]').forEach(b=>b.classList.toggle('active',b.dataset.boardTeam===state.boardTeam));refreshClipUI();updateSelection();autosave();storeTracks();toast(needsRelink?'Project opened. Import the original video to re-link it.':'Project opened.');}catch(err){toast(err.message);}e.target.value='';};
$('exportButton').onclick=()=>{modal('Take your analysis with you',`<p>Export what matters, with your current colors, overlays, and interpretation.</p><button class="button primary" id="exportFrame">Current frame · PNG</button><button class="button" id="exportProject">Editable project · JSON</button><button class="button" id="exportNotes">Analysis notes · TXT</button><button class="button" id="exportVideo">Annotated clip · WebM</button><p>Video export records the current canvas from the playhead to the end in real time, without audio. Keep this tab visible. Use a short clip for faster exports.</p>`);$('exportFrame').onclick=()=>{render();canvas.toBlob(b=>{if(b)download(b,`touchline-${fmt(time).replaceAll(':','-')}.png`);});$('modal').close();};$('exportProject').onclick=saveProject;$('exportNotes').onclick=()=>{const notes=state.title+'\n\n'+state.notes+'\n\n'+state.timedNotes.map(n=>`[${fmt(n.time)}] ${n.text}`).join('\n')+'\n\nVIDEO INTERPRETATIONS\n'+state.annotations.filter(a=>a.type==='text'&&a.text).map(a=>`[${fmt(a.start)}–${fmt(a.end)}] ${a.text}`).join('\n');download(new Blob([notes],{type:'text/plain'}),'touchline-notes.txt');};$('exportVideo').onclick=()=>{$('modal').close();recordVideo();};};
async function recordVideo(){if(recording||needsRelink)return;if(!window.MediaRecorder||!canvas.captureStream){toast('Video export is unavailable in this browser. Use a PNG snapshot.');return;}const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime){toast('This browser cannot record WebM video.');return;}if(time>=duration-.1)seek(0);if(duration-time>300){modal('Choose a shorter export',`<p>Video export is limited to 5 minutes per recording to keep memory use manageable. Move the playhead closer to the end, or use a shorter input clip.</p>`);return;}recording=true;const priorSpeed=$('playbackSpeed').value;$('playbackSpeed').value='1';video.playbackRate=1;const stream=canvas.captureStream(30),chunks=[];let recorder;try{recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:6000000});}catch(e){recording=false;stream.getTracks().forEach(t=>t.stop());toast(e.message);return;}recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};let stopTimer;recorder.onstop=()=>{clearInterval(stopTimer);stream.getTracks().forEach(t=>t.stop());recording=false;setPlaying(false);$('playbackSpeed').value=priorSpeed;video.playbackRate=+priorSpeed;download(new Blob(chunks,{type:mime}),'touchline-analysis.webm');$('exportButton').innerHTML=icon('export')+'Export';$('exportButton').onclick=exportHandler;toast('Annotated video exported without audio.');};const exportHandler=$('exportButton').onclick;$('exportButton').innerHTML=icon('pause')+'Stop export';$('exportButton').onclick=()=>{if(recorder.state==='recording')recorder.stop();};recorder.start(1000);setPlaying(true);toast('Recording your analysis. Keep this tab visible.');stopTimer=setInterval(()=>{if(!playing||time>=duration-.05){if(recorder.state==='recording')recorder.stop();}},150);}
$('helpButton').onclick=()=>modal('A little guidance. Your own perspective.',`<h3>1. Bring the match in</h3><p>Import a video from your computer. MP4 with H.264 works best. The initial tactical demo is simulated and clearly labeled.</p><h3>2. Follow the players</h3><p>Run the local app to analyze your footage with YOLO. Select a track, assign a team, and choose a label. Circles mark the bottom center of each detection; they are not pose-estimated foot keypoints.</p><h3>3. Make your point</h3><p>Draw lines, arrows, circles, and zones. Add a text box and write your own interpretation. Drawings start at the playhead and last 8 seconds by default. Select one to change timing, color, or thickness. Drag it to move; drag its bottom-right endpoint to resize.</p><h3>4. Understand the shape</h3><p>Choose a formation and drag the board markers. To map tracked players, calibrate four visible pitch corners. Optical flow compensates modest camera movement; cuts and large changes require recalibration. A formation template is your tactical reference, not an automatically inferred formation.</p><h3>5. Keep your work</h3><p>Edits autosave in this browser. Save a project file to keep tracking results and reopen the analysis elsewhere. Video files are not embedded; re-link the original clip. Export a PNG frame, notes, or a silent annotated WebM clip.</p><p><strong>Shortcuts:</strong> Space play/pause · ←/→ 5 seconds · V select · L line · A arrow · C circle · Z zone · T text · Ctrl+Z undo · Delete selected drawing.</p>`);
async function restore(){try{const saved=localStorage.getItem(storageKey);if(saved){state=sanitizeProject(JSON.parse(saved));needsRelink=!state.demo;duration=state.demo?60:state.clipDuration;}}catch{}for(const team of ['home','away'])if(!state.boards[team]?.length)initBoard(state.preset,team);$('formationPreset').value=state.preset;document.querySelectorAll('[data-board-team]').forEach(b=>b.classList.toggle('active',b.dataset.boardTeam===state.boardTeam));refreshClipUI();const db=await dbPromise;if(db&&!state.demo){try{const req=db.transaction('data').objectStore('data').get('tracks');req.onsuccess=()=>{const cached=req.result;if(cached?.sourceName===state.sourceName){frames=cached.frames||[];trackMeta=cached.meta;updateEngineStatus();}};}catch{}}checkEngine();}
// Follow the decoded video frame, rather than the audio/playback clock between frames.
let lastPresentedAt=-Infinity,lastPresentedMediaTime=0;
if(video.requestVideoFrameCallback){
 const onVideoFrame=(now,metadata)=>{lastPresentedAt=now;lastPresentedMediaTime=metadata.mediaTime;if(!state.demo&&!needsRelink){time=metadata.mediaTime;updateTime();render();}video.requestVideoFrameCallback(onVideoFrame);};
 video.addEventListener('seeking',()=>{lastPresentedAt=-Infinity;if(!state.demo&&!needsRelink){time=video.currentTime;updateTime();}});
 video.requestVideoFrameCallback(onVideoFrame);
}
